package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;import com.punjab.oms.ar.domain.query.finance.*;import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.nio.file.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-outbox-query：主体范围、运营权限及脱敏查询。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.outbox-query.real",matches="true") @EnabledIfSystemProperty(named="ar.outbox-query.real.commit",matches="true")
class OutboxQueryRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;@Autowired OutboxQueryService service;@Autowired ObjectMapper json;long scope;
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String file:List.of("V002__ar_audit.sql","V011__ar_outbox.sql"))for(String sql:Files.readString(Path.of("../scratch/dbddl/"+file)).split(";"))if(!sql.isBlank())jdbc.execute(sql);scope=UUID.randomUUID().getMostSignificantBits()>>>1;CurrentUser.set(new CurrentUser.Identity("query-test",Set.of(scope),Set.of("ar:outbox:read")));}
 @AfterEach void clear(){CurrentUser.clear();}
 long enqueue(){String key=UUID.randomUUID().toString();jdbc.update("INSERT INTO oms_ar_lifecycle_event(event_type,occurred_at,actor,correlation_id,created_by,updated_by) VALUES('TEST',NOW(6),'query-test',?,'query-test','query-test')",key);long event=jdbc.queryForObject("SELECT id FROM oms_ar_lifecycle_event WHERE correlation_id=?",Long.class,key);jdbc.update("INSERT INTO oms_ar_outbox(event_id,legal_entity_id,destination,payload,created_by,updated_by) VALUES(?,?,'FINANCE_EVENTS','{\"amount\":\"9999999999999999.12\"}','query-test','query-test')",event,scope);return jdbc.queryForObject("SELECT id FROM oms_ar_outbox WHERE event_id=?",Long.class,event);}
 OutboxPageQuery query(){var q=new OutboxPageQuery();q.setLegalEntityId(scope);return q;}
 @Test @DisplayName("列表总数与分页过滤一致，按ID倒序")void page(){long first=enqueue(),second=enqueue();jdbc.update("UPDATE oms_ar_outbox SET status='DEAD',last_error='TIMEOUT',attempt_count=3 WHERE id=?",second);var q=query();q.setSize(1);var page=service.page(q);assertThat(page.total()).isEqualTo(2);assertThat(page.records()).hasSize(1);assertThat(page.records().getFirst().id()).isEqualTo(second);q.setPage(2);assertThat(service.page(q).records().getFirst().id()).isEqualTo(first);q.setPage(1);q.setStatus("DEAD");page=service.page(q);assertThat(page.total()).isEqualTo(1);assertThat(page.records().getFirst().lastError()).isEqualTo("TIMEOUT");q.setEventId(jdbc.queryForObject("SELECT event_id FROM oms_ar_outbox WHERE id=?",Long.class,first));assertThat(service.page(q).total()).isZero();q.setEventId(null);q.setPage(Integer.MAX_VALUE);assertThat(service.page(q).records()).isEmpty();}
 @Test @DisplayName("详情保留原payload，列表与详情均不泄露租约令牌")void detail(){long id=enqueue();String token=UUID.randomUUID().toString();jdbc.update("UPDATE oms_ar_outbox SET status='PROCESSING',lease_token=?,lease_until=DATE_ADD(NOW(6),INTERVAL 30 SECOND) WHERE id=?",token,id);var result=service.detail(new OutboxDetailQuery(id,scope));assertThat(result).isNotNull();assertThat(result.payload().path("amount").asText()).isEqualTo("9999999999999999.12");assertThat(result.notification().leaseUntil()).isNotNull();assertThat(result.notification().id()).isEqualTo(id);String serialized=json.valueToTree(result).toString();assertThat(serialized).doesNotContain(token,"leaseToken","bearerToken");var page=json.valueToTree(service.page(query()));assertThat(page.toString()).doesNotContain(token,"payload","9999999999999999.12");}
 @Test @DisplayName("普通财务读权限不能读取通知原文，跨主体不可访问")void permissions(){long id=enqueue();CurrentUser.set(new CurrentUser.Identity("reader",Set.of(scope),Set.of("ar:read")));assertThatThrownBy(()->service.page(query())).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);CurrentUser.set(new CurrentUser.Identity("other",Set.of(scope+1),Set.of("ar:outbox:read")));assertThatThrownBy(()->service.detail(new OutboxDetailQuery(id,scope))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);assertThatThrownBy(()->service.detail(new OutboxDetailQuery(id,scope+1))).isInstanceOf(ServiceException.class).hasMessage("通知不存在或不可访问");var q=query();q.setLegalEntityId(scope+1);assertThat(service.page(q).total()).isZero();}
 @Test @DisplayName("逻辑删除不显示，非法参数拒绝")void invalid(){long id=enqueue();jdbc.update("UPDATE oms_ar_outbox SET delete_status=true WHERE id=?",id);assertThat(service.page(query()).total()).isZero();assertThatThrownBy(()->service.detail(new OutboxDetailQuery(id,scope))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.detail(null)).isInstanceOf(ServiceException.class);var q=query();q.setSize(201);assertThatThrownBy(()->service.page(q)).isInstanceOf(ServiceException.class);q.setSize(20);q.setStatus("invalid");assertThatThrownBy(()->service.page(q)).isInstanceOf(ServiceException.class);}
}
